/* v11: the editable header image fills the selected ribbon frame itself. */
[data-imory-edit-id="e0-0-1-1-0-0-0-c"]{
  position:relative;
}
[data-imory-edit-id="e0-0-1-1-0-0-0"]{
  position:absolute!important;
  inset:0!important;
  display:block!important;
  width:100%!important;
  max-width:none!important;
  height:100%!important;
  margin:0!important;
  aspect-ratio:auto!important;
  object-fit:fill!important;
  object-position:center!important;
}

/* v12: two compact Finder-style shortcuts per row. */
.finder-nav-shortcuts{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:5px 7px;
}
.finder-nav-shortcuts li{min-width:0}
.finder-nav-shortcuts a{
  display:flex;
  align-items:center;
  gap:7px;
  min-width:0;
  padding:7px 6px;
}
.finder-nav-text{
  min-width:0;
  overflow:hidden;
  text-overflow:ellipsis;
  white-space:nowrap;
}
.finder-nav-icon{
  position:relative;
  display:block;
  flex:0 0 15px;
  width:15px;
  height:15px;
  color:#9d8e95;
}

/* TXT / ordinary post: sheet with three text rules. */
.finder-nav-icon[data-kind="document"]{
  border:1px solid currentColor;
  border-radius:2px;
}
.finder-nav-icon[data-kind="document"]:before{
  content:"";
  position:absolute;
  left:3px;
  right:3px;
  top:4px;
  height:1px;
  background:currentColor;
  box-shadow:0 3px 0 currentColor,0 6px 0 currentColor;
}

/* IMG / gallery: framed landscape with a small sun. */
.finder-nav-icon[data-kind="image"]{
  overflow:hidden;
  border:1px solid currentColor;
  border-radius:2px;
}
.finder-nav-icon[data-kind="image"]:before{
  content:"";
  position:absolute;
  left:2px;
  bottom:-3px;
  width:8px;
  height:8px;
  border:1px solid currentColor;
  transform:rotate(45deg);
}
.finder-nav-icon[data-kind="image"]:after{
  content:"";
  position:absolute;
  top:2px;
  right:2px;
  width:3px;
  height:3px;
  border-radius:50%;
  background:currentColor;
}

/* BANNER / external link: a small hanging flag. */
.finder-nav-icon[data-kind="link"]{
  border:1px solid currentColor;
  border-radius:2px;
}
.finder-nav-icon[data-kind="link"]:before{
  content:"";
  position:absolute;
  left:3px;
  top:3px;
  width:8px;
  height:7px;
  background:currentColor;
  clip-path:polygon(0 0,100% 0,100% 100%,50% 72%,0 100%);
}

/* HIGHLIGHTS / quote: quotation marks. */
.finder-nav-icon[data-kind="quote"]:before{
  content:"“”;
  position:absolute;
  inset:-3px 0 0;
  color:currentColor;
  font-family:Georgia,serif;
  font-size:17px;
  font-weight:700;
  letter-spacing:-3px;
  line-height:15px;
  text-align:center;
}

