.foe-navigation{display:grid;grid-template-columns:180px minmax(0,1fr);gap:28px;margin-top:18px;padding:22px 0 0;border-top:1px solid var(--foe-deep)}.foe-nav-heading{display:flex;flex-direction:column}.foe-nav-heading span{font-family:Didot,'Bodoni 72',Georgia,serif;font-size:30px}.foe-nav-heading small{font-size:7px;letter-spacing:.17em}.foe-category-nav{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));border-top:1px solid var(--foe-line)}.foe-category-nav a{display:flex;align-items:center;justify-content:space-between;gap:14px;min-width:0;padding:13px 5px;border-bottom:1px solid var(--foe-line);color:var(--foe-ink);font-size:11px;font-weight:650;letter-spacing:.08em;text-decoration:none}.foe-category-nav a:nth-child(odd){padding-right:18px;border-right:1px solid var(--foe-line)}.foe-category-nav a:nth-child(even){padding-left:18px}.foe-category-nav a span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.foe-category-nav i{font-style:normal}.foe-bookmark-nav{grid-column:2;display:flex;flex-wrap:wrap;gap:8px}.foe-bookmark-nav a{padding:7px 10px;border:1px solid var(--foe-line);border-radius:999px;color:var(--foe-teal);font-size:8px;font-weight:700;letter-spacing:.13em;text-decoration:none}
.foe-home-feed{display:grid;grid-template-columns:minmax(0,1.12fr) minmax(280px,.88fr);gap:30px;margin-top:54px}.foe-home-feed header{display:flex;align-items:baseline;justify-content:space-between;gap:12px;padding-bottom:10px;border-bottom:1px solid var(--foe-deep)}.foe-home-feed header span{font-family:Georgia,serif;font-size:17px}.foe-home-feed header small,.foe-home-feed header a{color:var(--foe-teal);font-size:7px;letter-spacing:.16em;text-decoration:none}.foe-recent ol{margin:0;padding:0;list-style:none;counter-reset:foe-post}.foe-recent li{counter-increment:foe-post}.foe-recent li:nth-child(n+5){display:none}.foe-recent li a{display:grid;grid-template-columns:74px minmax(0,1fr) auto;align-items:center;gap:12px;padding:14px 2px;border-bottom:1px solid var(--foe-line);color:var(--foe-ink);text-decoration:none}.foe-recent li a:before{content:"0" counter(foe-post);color:var(--foe-gold);font-family:Georgia,serif;font-size:18px}.foe-recent li small{display:none}.foe-recent li strong{min-width:0;font-size:11px;font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.foe-recent li i{font-size:7px;font-style:normal;letter-spacing:.16em}.foe-highlight article{padding:18px 20px;border:1px solid var(--foe-line);border-top:0;background:rgba(234,245,242,.43)}.foe-highlight blockquote{margin:0;color:var(--foe-deep);font-family:Georgia,serif;font-size:14px;line-height:1.8}.foe-highlight article p{margin:12px 0 0;color:var(--foe-teal);font-size:10px;line-height:1.7}.foe-highlight article>a{display:block;margin-top:12px;color:var(--foe-gold);font-size:8px;text-decoration:none}.foe-empty{margin:0;padding:24px;border:1px solid var(--foe-line);border-top:0;color:var(--foe-teal);font-size:8px;letter-spacing:.14em}.foe-footer{display:flex;justify-content:space-between;gap:20px;width:min(1180px,100%);margin:auto;padding:34px clamp(18px,4vw,38px);color:var(--foe-teal);font-size:7px;letter-spacing:.2em}

/* Inner pages continue the same visual system. */
.finder-page{--finder-ink:var(--foe-ink);--finder-muted:#617878;--finder-line:rgba(7,47,48,.18);--finder-side:#dfecea;--finder-paper:var(--foe-paper);--finder-pink:#b7d8d2;--finder-pink-deep:var(--foe-teal);padding:42px 24px;background:linear-gradient(135deg,#dcecea,var(--foe-paper) 48%,#efe6d6);color:var(--foe-ink)}
.finder-window{border:1px solid var(--foe-deep);border-radius:0;background:var(--foe-paper);box-shadow:14px 14px 0 rgba(7,47,48,.12)}.finder-bar{border-color:var(--foe-deep);background:var(--foe-deep)}.finder-brand,.finder-bar-note{color:var(--foe-ice);letter-spacing:.18em}.finder-dots span,.finder-back-button,.finder-home-button{border:1px solid var(--foe-ice);background:transparent}.finder-dots span{background:var(--foe-gold)}.finder-home-button{background:var(--foe-cyan)}.finder-sidebar{background:#e4efec;border-color:var(--foe-line)}.finder-nav-label,.finder-kicker{color:var(--foe-teal);letter-spacing:.18em}.finder-main{background:var(--foe-paper)}.finder-content-head h1,.finder-article-head h1{font-family:Didot,'Bodoni 72',Georgia,serif;font-weight:400;letter-spacing:-.025em}.finder-folder{border-color:var(--foe-teal);background:linear-gradient(145deg,#d6ebe6,#abcfc8)}.finder-ios-document,.finder-document{border-color:var(--foe-teal);background:#edf7f4}.finder-highlight-card{border-radius:0;border-color:var(--foe-line);background:rgba(234,245,242,.35)}.finder-viewer-tools{color:var(--foe-teal)}

